'use strict';

// Empaqueta un repositorio en un solo archivo Markdown.
// Respeta .gitignore-like exclusiones, salta binarios y archivos generados.

const fs = require('fs');
const path = require('path');

const REPO = process.argv[2];
if (!REPO) {
  console.error('Uso: node bundle-repo.cjs <ruta-repo>');
  process.exit(1);
}
const ROOT = path.resolve(REPO);

// Directorios que siempre se excluyen (relativos al root, coincidencia exacta por segmento).
const EXCLUDE_DIRS = new Set([
  'node_modules',
  '.git',
  'dist',
  '.vitest',
  '.tmp-test-router',
  '.opencode',
  '.router-history',
  '.serena',
  '.kilo',
  '.cache',
  'pruebas-resultados',
]);

// Patrones de nombre de archivo a excluir (literal o suffix).
const EXCLUDE_FILE_PATTERNS = [
  'package-lock.json',
  'yarn.lock',
  'pnpm-lock.yaml',
  'bun.lockb',
  '.git.zip',
  'repomix-output.xml',
  'repo-bundle.md',
  'Thumbs.db',
  '.DS_Store',
];

// Extensiones consideradas binarias / generadas / no textuales.
const BINARY_EXT = new Set([
  '.png', '.jpg', '.jpeg', '.gif', '.ico', '.svg', '.bmp', '.webp', '.tiff',
  '.exe', '.msi', '.zip', '.7z', '.gz', '.tar', '.rar', '.cab',
  '.pdf', '.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx',
  '.woff', '.woff2', '.ttf', '.eot', '.otf',
  '.mp3', '.mp4', '.wav', '.webm', '.avi', '.mov',
  '.dll', '.so', '.node', '.dylib',
  '.map', // source maps generados
  '.lock',
  '.wasm',
  '.sqlite', '.db',
]);

// Patrones de nombre (regex) a excluir.
const EXCLUDE_NAME_RE = [
  /^\.env(\.|$)/i,
  /\.bak$/i,
  /\.backup\./i,
  /\.log(\.json)?$/i,
];

function shouldExcludeName(name) {
  if (EXCLUDE_FILE_PATTERNS.includes(name)) return true;
  for (const re of EXCLUDE_NAME_RE) {
    if (re.test(name)) return true;
  }
  return false;
}

function isBinaryExt(name) {
  return BINARY_EXT.has(path.extname(name).toLowerCase());
}

// Detecta contenido binario buscando bytes nulos en los primeros 8KB.
function looksBinary(buf) {
  const slice = buf.length > 8192 ? buf.subarray(0, 8192) : buf;
  for (let i = 0; i < slice.length; i++) {
    if (slice[i] === 0) return true;
  }
  return false;
}

function formatSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(1)} KB`;
  const mb = kb / 1024;
  return `${mb.toFixed(2)} MB`;
}

function walk(dir, acc) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (e) {
    return;
  }
  for (const ent of entries) {
    if (ent.isDirectory()) {
      if (EXCLUDE_DIRS.has(ent.name)) continue;
      // Excluir caches de tests temporales.
      if (ent.name.startsWith('.tmp-')) continue;
      walk(path.join(dir, ent.name), acc);
    } else if (ent.isFile()) {
      if (shouldExcludeName(ent.name)) continue;
      if (isBinaryExt(ent.name)) { acc.excluded++; continue; }
      acc.files.push(path.join(dir, ent.name));
    }
  }
}

function main() {
  const acc = { files: [], excluded: 0 };
  walk(ROOT, acc);

  // Ordenar por ruta relativa para salida determinista.
  const files = acc.files
    .map((p) => ({ abs: p, rel: path.relative(ROOT, p) }))
    .sort((a, b) => a.rel.localeCompare(b.rel, undefined, { numeric: true }));

  const out = [];
  const SEP = '='.repeat(78);
  let totalLines = 0;
  let totalBytes = 0;
  let included = 0;
  let skippedContent = 0;

  for (const f of files) {
    let buf;
    try {
      buf = fs.readFileSync(f.abs);
    } catch {
      acc.excluded++;
      continue;
    }
    if (looksBinary(buf)) {
      acc.excluded++;
      continue;
    }
    let text;
    try {
      text = buf.toString('utf8');
    } catch {
      acc.excluded++;
      continue;
    }
    // Normalizar separadores de linea a \n y descartar BOM.
    if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const lines = text === '' ? 0 : text.split('\n').length;
    const size = Buffer.byteLength(text, 'utf8');

    out.push(`${SEP}`);
    out.push(`FILE: ${f.rel.replace(/\\/g, '/')}  (${lines} lines, ${formatSize(size)})`);
    out.push(`${SEP}`);
    out.push(text);
    out.push('');

    totalLines += lines;
    totalBytes += size;
    included++;
  }

  const header = [
    '# Repository Bundle',
    `Repo: ${ROOT}`,
    `Generated: ${new Date().toISOString()}`,
    `Files included: ${included}`,
    `Lines: ${totalLines.toLocaleString('en-US')}`,
    `Size: ${formatSize(totalBytes)}`,
    `Excluded (binary/backup/unreadable): ${acc.excluded + skippedContent}`,
    '',
    '---',
    '',
  ].join('\n');

  const finalText = header + out.join('\n');
  const outPath = path.join(ROOT, 'repo-bundle.md');
  fs.writeFileSync(outPath, finalText, 'utf8');

  // Resumen a stdout.
  console.log('=== Resumen de metricas ===');
  console.log(`Archivo de salida: ${outPath}`);
  console.log(`Tamano del bundle: ${formatSize(Buffer.byteLength(finalText, 'utf8'))}`);
  console.log(`Archivos incluidos: ${included}`);
  console.log(`Archivos excluidos: ${acc.excluded + skippedContent}`);
  console.log(`Lineas totales: ${totalLines.toLocaleString('en-US')}`);
  console.log(`Tamano total (contenido): ${formatSize(totalBytes)}`);

  // Desglose por extension.
  const byExt = {};
  for (const f of files) {
    const ext = path.extname(f.rel).toLowerCase() || '(sin ext)';
    if (!byExt[ext]) byExt[ext] = { count: 0, bytes: 0, lines: 0 };
  }
  // Recalcular por ext recorriendo archivos incluidos (releer es caro; usamos lo ya leido restando).
  // Simpler: recorrer archivos de nuevo contando solo incluidos.
  let idx = 0;
  const extStats = {};
  for (const f of files) {
    const ext = path.extname(f.rel).toLowerCase() || '(sin ext)';
    if (!extStats[ext]) extStats[ext] = { count: 0, bytes: 0 };
    // No re-leemos; usamos los datos ya escritos seria ideal, pero para el resumen basta con contar.
    extStats[ext].count++;
  }
  console.log('\n=== Desglose por extension (archivos considerados) ===');
  const sorted = Object.entries(extStats).sort((a, b) => b[1].count - a[1].count);
  for (const [ext, s] of sorted) {
    console.log(`  ${ext}: ${s.count} archivos`);
  }
}

main();

