const out = [];
const SEP = '='.repeat(78);
let totalLines = 0;
let totalBytes = 0;
let included = 0;
const extStats = {};

for (const f of files) {
  let buf;
  try {
    buf = fs.readFileSync(f.abs);
  } catch {
    acc.excluded++;
    continue;
  }
  if (looksBinary(buf)) {
    acc.excluded++;
    continue;
  }
  let text;
  try {
    text = buf.toString('utf8');
  } catch {
    acc.excluded++;
    continue;
  }
  // Normalizar separadores de linea a \n y descartar BOM.
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const lines = text === '' ? 0 : text.split('\n').length;
  const size = Buffer.byteLength(text, 'utf8');

  out.push(`${SEP}`);
  out.push(`FILE: ${f.rel.replace(/\\/g, '/')}  (${lines} lines, ${formatSize(size)})`);
  out.push(`${SEP}`);
  out.push(text);
  out.push('');

  totalLines += lines;
  totalBytes += size;
  included++;

  const ext = path.extname(f.rel).toLowerCase() || '(sin ext)';
  if (!extStats[ext]) extStats[ext] = { count: 0, bytes: 0, lines: 0 };
  extStats[ext].count++;
  extStats[ext].bytes += size;
  extStats[ext].lines += lines;
}

